	private static final class ThrowingUnauthorizedWorkbenchServlet extends TestWorkbenchServlet {
		@Override
		protected TupleResultBuilder getTupleResultBuilder(HttpServletRequest req, HttpServletResponse resp,
				java.io.OutputStream outputStream) {
			TupleResultBuilder builder = mock(TupleResultBuilder.class);
			try {
				when(builder.start(any(String[].class)))
						.thenThrow(new org.eclipse.rdf4j.query.QueryResultHandlerException("boom"));
			} catch (org.eclipse.rdf4j.query.QueryResultHandlerException e) {
				throw new AssertionError(e);
			}
			return builder;
		}
	}

	private static final class RecordingProxyRepositoryServlet extends ProxyRepositoryServlet {
		private int initCount;
		private int serviceCount;
		private int destroyCount;
		private int resetCount;
		private String lastServletPath;
		private String lastPathInfo;
		private RepositoryManager assignedManager;
		private RepositoryInfo assignedInfo;
		private Repository assignedRepository;
		private Throwable toThrow;
		private String writtenBeforeThrowing;
		private boolean sentPageBeforeThrowing;
		private CountDownLatch serviceEntered;
		private CountDownLatch serviceRelease;

		@Override
		public void setRepositoryManager(RepositoryManager manager) {
			assignedManager = manager;
		}

		@Override
		public void setRepositoryInfo(RepositoryInfo info) {
			assignedInfo = info;
		}

		@Override
		public void setRepository(Repository repository) {
			assignedRepository = repository;
		}

		@Override
		public void init(ServletConfig config) {
			initCount++;
		}

		@Override
		public void service(HttpServletRequest req, HttpServletResponse resp) throws ServletException {
			serviceCount++;
			if (serviceEntered != null && serviceEntered.getCount() > 0) {
				serviceEntered.countDown();
				try {
					if (!serviceRelease.await(30, TimeUnit.SECONDS)) {
						throw new ServletException("Timed out waiting for the test's active request release");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new ServletException(e);
				}
			}
			lastServletPath = req.getServletPath();
			lastPathInfo = req.getPathInfo();
			if (sentPageBeforeThrowing) {
				// As a page does that sends its view and links at once, so that the browser loads them meanwhile.
				try {
					WorkbenchPageResultWriter writer = new WorkbenchPageResultWriter(resp.getOutputStream());
					req.setAttribute(WorkbenchPageProtocol.PAGE_RESULT_WRITER_ATTRIBUTE, writer);
					writer.view("repositories");
					writer.startQueryResult(List.of("id"));
					writer.flush();
					resp.flushBuffer();
				} catch (IOException | QueryResultHandlerException e) {
					throw new ServletException(e);
				}
			}
			if (writtenBeforeThrowing != null) {
				try {
					resp.getOutputStream().write(writtenBeforeThrowing.getBytes(StandardCharsets.UTF_8));
				} catch (IOException e) {
					throw new ServletException(e);
				}
			}
			if (toThrow != null) {
				if (toThrow instanceof ServletException) {
					throw (ServletException) toThrow;
				}
				if (toThrow instanceof RuntimeException) {
					throw (RuntimeException) toThrow;
				}
			}
		}

		@Override
		public void destroy() {
			destroyCount++;
		}

		@Override
		public void resetCache() {
			resetCount++;
		}
	}

	private static final class FixedCookieHandler extends CookieHandler {
		private final String value;

		private FixedCookieHandler(String value) {
			super((String) null);
			this.value = value;
		}

		@Override
		protected String getCookieNullIfEmpty(HttpServletRequest req, HttpServletResponse resp, String name) {
			return value;
		}
	}

	private static final class ValidationFailure extends RuntimeException implements ValidationException {
		private final Model model = new LinkedHashModel();

		private ValidationFailure() {
			model.add(SimpleValueFactory.getInstance().createIRI("urn:report"), RDF.TYPE, SHACL.VALIDATION_REPORT);
		}

		@Override
		public Model validationReportAsModel() {
			return model;
		}
	}
